 68→void FFrameProducer::OnFrameBufferReady(SWindow& SlateWindow, const FTextureRHIRef& FrameBuffer)
 69→{
 70→	// This runs on the render thread -- must be fast when skipping
 71→
 72→	// Throttle gate: skip if too soon since last capture
 73→	const double Now = FPlatformTime::Seconds();
 74→	if ((Now - LastCaptureTime) < MinCaptureInterval)
 75→	{
 76→		return;
 77→	}
 78→
 79→	if (!PixelBus || !FrameBuffer.IsValid())
 80→	{
 81→		return;
 82→	}
 83→
 84→	LastCaptureTime = Now;
 85→	const int64 PrevFrame = FrameCounter.Load();
 86→	const int64 CurrentFrame = PrevFrame + 1;
 87→	FrameCounter.Store(CurrentFrame);
 88→
 89→	// Read the backbuffer pixels
 90→	const FIntPoint Size = FrameBuffer->GetSizeXY();
 91→	TArray<FColor> Pixels;
 92→
 93→	FReadSurfaceDataFlags ReadFlags(RCM_UNorm);
 94→	ReadFlags.SetLinearToGamma(false);
 95→
 96→	// ReadSurfaceData on the current RHI command list
 97→	FRHICommandListImmediate& RHICmdList = FRHICommandListImmediate::Get();
 98→	RHICmdList.ReadSurfaceData(
 99→		FrameBuffer,
100→		FIntRect(0, 0, Size.X, Size.Y),
101→		Pixels,
102→		ReadFlags
103→	);
104→
105→	if (Pixels.Num() > 0)
106→	{
107→		PixelBus->WriteFrame(MoveTemp(Pixels), Size, CurrentFrame, Now);
108→	}
109→}
