15→FPerceptionMetadata FMetadataCollector::Collect()
16→{
17→	check(IsInGameThread());
18→
19→	FPerceptionMetadata Meta;
20→
21→	// Get the active level editor viewport
22→	if (GEditor)
23→	{
24→		// Try to get the active viewport client
25→		FEditorViewportClient* ViewportClient = nullptr;
26→
27→		FLevelEditorModule& LevelEditorModule = FModuleManager::GetModuleChecked<FLevelEditorModule>("LevelEditor");
28→		TSharedPtr<ILevelEditor> LevelEditor = LevelEditorModule.GetFirstLevelEditor();
29→		if (LevelEditor.IsValid())
30→		{
31→			TSharedPtr<SLevelViewport> ActiveViewport = LevelEditor->GetActiveViewportInterface();
32→			if (ActiveViewport.IsValid())
33→			{
34→				ViewportClient = &ActiveViewport->GetLevelViewportClient();
35→			}
36→		}
37→
38→		if (ViewportClient)
39→		{
40→			// Camera
41→			Meta.Camera.Location = ViewportClient->GetViewLocation();
42→			Meta.Camera.Rotation = ViewportClient->GetViewRotation();
43→			Meta.Camera.FOV = ViewportClient->ViewFOV;
44→
45→			// Viewport size
46→			FIntPoint ViewSize = ViewportClient->Viewport ? ViewportClient->Viewport->GetSizeXY() : FIntPoint::ZeroValue;
47→			Meta.ViewportSize = ViewSize;
48→
49→			// Viewport type
50→			if (ViewportClient->IsSimulateInEditorViewport())
51→			{
52→				Meta.ViewportType = TEXT("SIE");
53→			}
54→			else if (GEditor->PlayWorld != nullptr)
55→			{
56→				Meta.ViewportType = TEXT("PIE");
57→			}
58→			else
59→			{
60→				Meta.ViewportType = TEXT("LevelEditor");
61→			}
62→		}
63→
64→		// Selected actors
65→		USelection* Selection = GEditor->GetSelectedActors();
66→		if (Selection)
67→		{
68→			for (int32 i = 0; i < Selection->Num(); ++i)
69→			{
70→				AActor* Actor = Cast<AActor>(Selection->GetSelectedObject(i));
71→				if (Actor)
72→				{
73→					Meta.SelectedActors.Add(Actor->GetActorLabel());
74→				}
75→			}
76→		}
77→
78→		// Map name and actor count
79→		UWorld* World = GEditor->GetEditorWorldContext().World();
80→		if (World)
81→		{
82→			Meta.MapName = World->GetMapName();
83→
84→			int32 Count = 0;
85→			for (TActorIterator<AActor> It(World); It; ++It)
86→			{
87→				++Count;
88→			}
89→			Meta.ActorCount = Count;
90→		}
91→
92→		// Timing
93→		Meta.DeltaTime = FApp::GetDeltaTime();
94→		Meta.FPS = (Meta.DeltaTime > 0.0f) ? (1.0f / Meta.DeltaTime) : 0.0f;
95→	}
96→
97→	return Meta;
98→}
