  9→TArray<FColor> FPerceptionAdapter::Resize(const TArray<FColor>& Source,
 10→                                           FIntPoint SourceSize, FIntPoint TargetSize)
 11→{
 12→	if (SourceSize == TargetSize || Source.Num() == 0)
 13→	{
 14→		return Source;  // No resize needed
 15→	}
 16→
 17→	const int32 SrcW = SourceSize.X;
 18→	const int32 SrcH = SourceSize.Y;
 19→	const int32 DstW = TargetSize.X;
 20→	const int32 DstH = TargetSize.Y;
 21→
 22→	TArray<FColor> Result;
 23→	Result.SetNumUninitialized(DstW * DstH);
 24→
 25→	// Bilinear interpolation
 26→	const float ScaleX = static_cast<float>(SrcW) / static_cast<float>(DstW);
 27→	const float ScaleY = static_cast<float>(SrcH) / static_cast<float>(DstH);
 28→
 29→	for (int32 Y = 0; Y < DstH; ++Y)
 30→	{
 31→		const float SrcY = (Y + 0.5f) * ScaleY - 0.5f;
 32→		const int32 Y0 = FMath::Clamp(FMath::FloorToInt32(SrcY), 0, SrcH - 1);
 33→		const int32 Y1 = FMath::Clamp(Y0 + 1, 0, SrcH - 1);
 34→		const float FracY = SrcY - Y0;
 35→
 36→		for (int32 X = 0; X < DstW; ++X)
 37→		{
 38→			const float SrcX = (X + 0.5f) * ScaleX - 0.5f;
 39→			const int32 X0 = FMath::Clamp(FMath::FloorToInt32(SrcX), 0, SrcW - 1);
 40→			const int32 X1 = FMath::Clamp(X0 + 1, 0, SrcW - 1);
 41→			const float FracX = SrcX - X0;
 42→
 43→			// Sample 4 neighbors
 44→			const FColor& C00 = Source[Y0 * SrcW + X0];
 45→			const FColor& C10 = Source[Y0 * SrcW + X1];
 46→			const FColor& C01 = Source[Y1 * SrcW + X0];
 47→			const FColor& C11 = Source[Y1 * SrcW + X1];
 48→
 49→			// Bilinear blend
 50→			const float OneMinusFX = 1.0f - FracX;
 51→			const float OneMinusFY = 1.0f - FracY;
 52→
 53→			const uint8 R = static_cast<uint8>(FMath::Clamp(
 54→				C00.R * OneMinusFX * OneMinusFY + C10.R * FracX * OneMinusFY +
 55→				C01.R * OneMinusFX * FracY + C11.R * FracX * FracY, 0.0f, 255.0f));
 56→			const uint8 G = static_cast<uint8>(FMath::Clamp(
 57→				C00.G * OneMinusFX * OneMinusFY + C10.G * FracX * OneMinusFY +
 58→				C01.G * OneMinusFX * FracY + C11.G * FracX * FracY, 0.0f, 255.0f));
 59→			const uint8 B = static_cast<uint8>(FMath::Clamp(
 60→				C00.B * OneMinusFX * OneMinusFY + C10.B * FracX * OneMinusFY +
 61→				C01.B * OneMinusFX * FracY + C11.B * FracX * FracY, 0.0f, 255.0f));
 62→			const uint8 A = 255;
 63→
 64→			Result[Y * DstW + X] = FColor(R, G, B, A);
 65→		}
 66→	}
 67→
 68→	return Result;
 69→}
