 71→TArray<uint8> FPerceptionAdapter::Encode(const TArray<FColor>& Pixels, FIntPoint Size,
 72→                                          EPerceptionImageFormat Format, int32 Quality)
 73→{
 74→	TArray<uint8> Result;
 75→
 76→	if (Pixels.Num() == 0 || Size.X <= 0 || Size.Y <= 0)
 77→	{
 78→		return Result;
 79→	}
 80→
 81→	IImageWrapperModule& ImageWrapperModule = FModuleManager::LoadModuleChecked<IImageWrapperModule>("ImageWrapper");
 82→
 83→	const EImageFormat ImageFormat = (Format == EPerceptionImageFormat::PNG) ? EImageFormat::PNG : EImageFormat::JPEG;
 84→	TSharedPtr<IImageWrapper> ImageWrapper = ImageWrapperModule.CreateImageWrapper(ImageFormat);
 85→
 86→	if (!ImageWrapper.IsValid())
 87→	{
 88→		UE_LOG(LogViewportPerception, Warning, TEXT("Failed to create image wrapper"));
 89→		return Result;
 90→	}
 91→
 92→	// Set raw pixel data
