 94→	if (ImageWrapper->SetRaw(
 95→		Pixels.GetData(),
 96→		Pixels.Num() * sizeof(FColor),
 97→		Size.X,
 98→		Size.Y,
 99→		ERGBFormat::BGRA,
100→		8))
101→	{
