223→bool FPerceptionEndpoint::HandleConfig(const FHttpServerRequest& Request,
224→                                        const FHttpResultCallback& OnComplete)
225→{
226→	if (!Subsystem)
227→	{
228→		SendJsonResponse(OnComplete, TEXT("{\"error\":\"Subsystem not available\"}"), 503);
229→		return true;
230→	}
231→
232→	// Parse request body as JSON
233→	if (Request.Body.Num() == 0)
234→	{
235→		SendJsonResponse(OnComplete, TEXT("{\"status\":\"no changes\"}"));
236→		return true;
237→	}
238→
239→	FString BodyStr = UTF8_TO_TCHAR(reinterpret_cast<const char*>(Request.Body.GetData()));
240→	TSharedRef<TJsonReader<>> Reader = TJsonReaderFactory<>::Create(BodyStr);
241→	TSharedPtr<FJsonObject> Body;
242→
243→	if (FJsonSerializer::Deserialize(Reader, Body) && Body.IsValid())
244→	{
245→		double MaxFPS;
246→		if (Body->TryGetNumberField(TEXT("max_fps"), MaxFPS))
247→		{
248→			Subsystem->SetMaxCaptureRate(static_cast<float>(MaxFPS));
249→		}
250→
251→		int32 Width = 0, Height = 0;
252→		if (Body->TryGetNumberField(TEXT("width"), Width) &&
253→		    Body->TryGetNumberField(TEXT("height"), Height))
254→		{
255→			Subsystem->SetCaptureResolution(Width, Height);
256→		}
257→
258→		FString Format;
259→		if (Body->TryGetStringField(TEXT("format"), Format))
260→		{
261→			Subsystem->SetImageFormat(
262→				Format.Equals(TEXT("png"), ESearchCase::IgnoreCase)
263→					? EPerceptionImageFormat::PNG
264→					: EPerceptionImageFormat::JPEG
265→			);
266→		}
267→
268→		int32 Quality;
269→		if (Body->TryGetNumberField(TEXT("quality"), Quality))
270→		{
271→			Subsystem->SetJPEGQuality(Quality);
272→		}
273→	}
274→
275→	SendJsonResponse(OnComplete, TEXT("{\"status\":\"configured\"}"));
276→	return true;
277→}
