281→{
282→	if (!Subsystem)
283→	{
284→		SendJsonResponse(OnComplete, TEXT("{\"error\":\"Subsystem not available\"}"), 503);
285→		return true;
286→	}
287→
288→	// Parse optional params from body (defaults used if body is empty)
289→	float FPS = 5.0f;
290→	int32 Width = 1280, Height = 720;
291→
292→	if (Request.Body.Num() > 0)
293→	{
294→		FString BodyStr = UTF8_TO_TCHAR(reinterpret_cast<const char*>(Request.Body.GetData()));
295→		TSharedRef<TJsonReader<>> Reader = TJsonReaderFactory<>::Create(BodyStr);
296→		TSharedPtr<FJsonObject> Body;
