299→		{
300→			double V;
301→			if (Body->TryGetNumberField(TEXT("fps"), V)) FPS = static_cast<float>(V);
302→			Body->TryGetNumberField(TEXT("width"), Width);
303→			Body->TryGetNumberField(TEXT("height"), Height);
304→		}
305→	}
306→
307→	Subsystem->StartCapture(FPS, Width, Height);
308→	SendJsonResponse(OnComplete, TEXT("{\"status\":\"capturing\"}"));
