114→FPerceptionPacket UViewportPerceptionSubsystem::GetLatestPacket()
115→{
116→	FPerceptionPacket Packet;
117→
118→	if (!Bus)
119→	{
120→		return Packet;
121→	}
122→
123→	TArray<FColor> RawPixels;
124→	FIntPoint RawSize;
125→	FPerceptionMetadata Meta;
126→	int64 FrameNum;
127→	double Timestamp;
128→
129→	if (!Bus->ReadLatestWithMetadata(RawPixels, RawSize, Meta, FrameNum, Timestamp))
130→	{
131→		return Packet;
132→	}
133→
134→	LastSeenFrame = FrameNum;
135→
136→	// Resize if needed
137→	TArray<FColor> Pixels = (RawSize != CaptureResolution)
138→		? FPerceptionAdapter::Resize(RawPixels, RawSize, CaptureResolution)
139→		: MoveTemp(RawPixels);
140→
141→	// Encode
142→	TArray<uint8> Encoded = FPerceptionAdapter::Encode(Pixels, CaptureResolution, ImageFormat, JPEGQuality);
143→
144→	if (Encoded.Num() == 0)
145→	{
146→		return Packet;
147→	}
148→
149→	Packet.ImageData = MoveTemp(Encoded);
150→	Packet.Width = CaptureResolution.X;
151→	Packet.Height = CaptureResolution.Y;
152→	Packet.Format = ImageFormat;
153→	Packet.FrameNumber = FrameNum;
154→	Packet.Timestamp = Timestamp;
155→	Packet.Metadata = Meta;
156→	Packet.bValid = true;
157→
158→	return Packet;
159→}
