171→void UViewportPerceptionSubsystem::OnTick(float DeltaTime)
172→{
173→	if (!bCapturing || !Bus || !Collector)
174→	{
175→		return;
176→	}
177→
178→	// Attach metadata to the latest frame
179→	if (Bus->HasNewFrame(LastSeenFrame))
180→	{
181→		FPerceptionMetadata Meta = Collector->Collect();
